pub proof fn always_and_equality<T>(p: TempPred<T>, q: TempPred<T>)
    ensures always(p.and(q)) == always(p).and(always(q)),
{
    let left = always(p.and(q));
    let right = always(p).and(always(q));

    // Show left entails right
    assert(left.entails(right)) by {
        assert forall |ex: Execution<T>| left.satisfied_by(ex) ==> right.satisfied_by(ex) by {
            if left.satisfied_by(ex) {
                let H = left.satisfied_by(ex);

                assert(always(p).satisfied_by(ex)) by {
                    assert forall |i: nat| p.satisfied_by(ex.suffix(i)) by {
                        let hpq = H(i);
                        assert hpq;
                        // hpq = p.satisfied_by(ex.suffix(i)) && q.satisfied_by(ex.suffix(i))
                        assert(p.satisfied_by(ex.suffix(i)));
                    };
                };

                assert(always(q).satisfied_by(ex)) by {
                    assert forall |i: nat| q.satisfied_by(ex.suffix(i)) by {
                        let hpq = H(i);
                        assert hpq;
                        assert(q.satisfied_by(ex.suffix(i)));
                    };
                };

                assert(right.satisfied_by(ex));
            }
        };
    };

    // Show right entails left
    assert(right.entails(left)) by {
        assert forall |ex: Execution<T>| right.satisfied_by(ex) ==> left.satisfied_by(ex) by {
            if right.satisfied_by(ex) {
                let H = right.satisfied_by(ex);

                // left.satisfied_by(ex) is a forall that requires both p and q
                assert(left.satisfied_by(ex)) by {
                    assert forall |i: nat| (p.and(q)).satisfied_by(ex.suffix(i)) by {
                        let hp = H.0;
                        let hq = H.1;
                        // But H is a bool from &&; we cannot index it.
                    };
                };
            }
        };
    };

    temp_pred_equality(left, right);
}

